{"hypotheses": [
  {"name": "Hypothesis 1", 
   "mechanism": "Firms with higher R&D and inventory growth are likely to have future innovative products leading to higher returns.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "RD"}, 
       {"weight": 1.0, "primitive": "InvGrowth"}
     ], 
     "regime": "MKT_TRAILING_12M_UP", 
     "vol_target": true},
   "auxiliary_predictions": [
     {"type": "size_segment", "segment": "small", "direction": "stronger"}, 
     {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}, 
     {"type": "correlation", "primitive": "RD", "bound": "above", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.6, 
   "expected_decay_half_life_months": 36},

  {"name": "Hypothesis 2", 
   "mechanism": "Firms with high cash reserves and high book to market values are likely to be undervalued, leading to higher returns.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "Cash"}, 
       {"weight": 1.0, "primitive": "BM"}
     ], 
     "regime": "MKT_TRAILING_12M_DOWN", 
     "vol_target": false},
   "auxiliary_predictions": [
     {"type": "size_segment", "segment": "large", "direction": "stronger"}, 
     {"type": "correlation", "primitive": "BM", "bound": "above", "threshold": 0.3}, 
     {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"}
   ], 
   "expected_annualized_sharpe": 0.5, 
   "expected_decay_half_life_months": 24},

  {"name": "Hypothesis 3", 
   "mechanism": "Firms with high short interest and recent equity issuance are prone to short squeeze, leading to higher returns.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "ShortInterest"}, 
       {"weight": 1.0, "primitive": "ShareIss1Y"}
     ], 
     "regime": "VIX_ABOVE_TRAILING_MEDIAN", 
     "vol_target": true},
   "auxiliary_predictions": [
     {"type": "size_segment", "segment": "micro", "direction": "stronger"}, 
     {"type": "international", "region": "emerging", "direction": "same_sign"}, 
     {"type": "correlation", "primitive": "ShortInterest", "bound": "above", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.7, 
   "expected_decay_half_life_months": 18},

  {"name": "Hypothesis 4", 
   "mechanism": "Firms with high advertising expenditure and firm age can induce customer loyalty, leading to higher returns.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "AdExp"}, 
       {"weight": 1.0, "primitive": "FirmAge"}
     ], 
     "regime": "TERM_SPREAD_POSITIVE", 
     "vol_target": true},
   "auxiliary_predictions": [
     {"type": "size_segment", "segment": "mega", "direction": "stronger"}, 
     {"type": "correlation", "primitive": "AdExp", "bound": "above", "threshold": 0.3}, 
     {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"}
   ], 
   "expected_annualized_sharpe": 0.4, 
   "expected_decay_half_life_months": 30},

  {"name": "Hypothesis 5", 
   "mechanism": "Firms with high asset growth and low earnings consistency are likely to be overvalued and mean revert, leading to lower returns.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "AssetGrowth"}, 
       {"weight": -1.0, "primitive": "EarningsConsistency"}
     ], 
     "regime": "MKT_TRAILING_12M_UP", 
     "vol_target": false},
   "auxiliary_predictions": [
     {"type": "size_segment", "segment": "large", "direction": "stronger"}, 
     {"type": "correlation", "primitive": "EarningsConsistency", "bound": "below", "threshold": 0.3}, 
     {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "lower"}
   ], 
   "expected_annualized_sharpe": 0.5, 
   "expected_decay_half_life_months": 12},

  {"name": "Hypothesis 6", 
   "mechanism": "Firms with high R&D capital to assets and recent patenting activity are likely to have future innovative products leading to higher returns.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "RDcap"}, 
       {"weight": 1.0, "primitive": "PatentsRD"}
     ], 
     "regime": "VIX_BELOW_TRAILING_MEDIAN", 
     "vol_target": true},
   "auxiliary_predictions": [
     {"type": "size_segment", "segment": "small", "direction": "stronger"}, 
     {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}, 
     {"type": "correlation", "primitive": "RDcap", "bound": "above", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.6, 
   "expected_decay_half_life_months": 24},

  {"name": "Hypothesis 7", 
   "mechanism": "Firms with high book leverage and high market leverage are likely to be overleveraged and riskier, leading to higher expected returns.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "BookLeverage"}, 
       {"weight": 1.0, "primitive": "Leverage"}
     ], 
     "regime": "VIX_ABOVE_TRAILING_MEDIAN", 
     "vol_target": false},
   "auxiliary_predictions": [
     {"type": "size_segment", "segment": "micro", "direction": "stronger"}, 
     {"type": "international", "region": "emerging", "direction": "same_sign"}, 
     {"type": "correlation", "primitive": "Leverage", "bound": "above", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.7, 
   "expected_decay_half_life_months": 12},

  {"name": "Hypothesis 8", 
   "mechanism": "Firms with high past trading volume and high share volume are likely to have high liquidity, leading to lower expected returns.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "DolVol"}, 
       {"weight": 1.0, "primitive": "ShareVol"}
     ], 
     "regime": "VIX_BELOW_TRAILING_MEDIAN", 
     "vol_target": false},
   "auxiliary_predictions": [
     {"type": "size_segment", "segment": "mega", "direction": "weaker"}, 
     {"type": "correlation", "primitive": "DolVol", "bound": "above", "threshold": 0.3}, 
     {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "lower"}
   ], 
   "expected_annualized_sharpe": 0.3, 
   "expected_decay_half_life_months": 18}
]}
